<main class="section"><div class="section-head"><div><span class="eyebrow">Ankauf</span><h1>Angebote</h1></div><div class="actions"><a class="btn" href="/admin">Dashboard</a><a class="btn primary" href="/admin/angebote/neu">Neues Angebot</a></div></div><div class="table-wrap"><table><thead><tr><th>Titel</th><th>Kategorie</th><th>Version</th><th>Vergütung</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($offers as $o):?><tr><td><strong><?=App\Core\View::e($o['title'])?></strong><?php if($o['is_private']):?><small>Privatangebot</small><?php endif;?></td><td><?=App\Core\View::e($o['category_name'])?></td><td>v<?= (int)$o['version_no'] ?></td><td><?=number_format((float)$o['compensation'],2,',','.')?> €</td><td><?=App\Core\View::e($o['status'])?></td><td><a class="btn" href="/admin/angebote/<?=$o['id']?>/bearbeiten">Bearbeiten</a></td></tr><?php endforeach;?></tbody></table><?php if(!$offers):?><div class="empty">Noch keine Angebote vorhanden.</div><?php endif;?></div></main>